import json
from pathlib import Path
from docx import Document

DATA_PATH=Path('/root/employee_data.json')
TEMPLATE_PATH=Path('/root/offer_letter_template.docx')
OUTPUT_PATH=Path('/root/offer_letter_filled.docx')

data=json.loads(DATA_PATH.read_text())
relocation_yes=str(data.get('RELOCATION_PACKAGE','')).strip().lower()=='yes'

# mapping of placeholders to values (stringified)
replacements={k: str(v) for k,v in data.items()}


def replace_range_in_runs(paragraph, start, end, replacement):
    runs = paragraph.runs
    if start == end:
        return
    # find start and end run indices and offsets
    cum = 0
    si = ei = None
    s_off = e_off = None
    for i, r in enumerate(runs):
        t = r.text or ''
        l = len(t)
        if si is None and start < cum + l:
            si = i
            s_off = start - cum
        if ei is None and end <= cum + l:
            ei = i
            e_off = end - cum
            break
        cum += l
    if si is None:
        return
    if ei is None:
        ei = len(runs) - 1
        e_off = len(runs[ei].text or '')
    if si == ei:
        t = runs[si].text or ''
        runs[si].text = t[:s_off] + replacement + t[e_off:]
        return
    start_text = runs[si].text or ''
    end_text = runs[ei].text or ''
    runs[si].text = start_text[:s_off] + replacement
    for j in range(si + 1, ei):
        runs[j].text = ''
    runs[ei].text = end_text[e_off:]


def replace_in_runs(paragraph, token, replacement):
    if not token:
        return
    while True:
        combined = ''.join(r.text or '' for r in paragraph.runs)
        idx = combined.find(token)
        if idx == -1:
            break
        replace_range_in_runs(paragraph, idx, idx + len(token), replacement)


def process_paragraph(paragraph):
    combined = ''.join(r.text or '' for r in paragraph.runs)
    removed_conditional = False
    if '{{IF_RELOCATION}}' in combined and '{{END_IF_RELOCATION}}' in combined:
        if relocation_yes:
            replace_in_runs(paragraph, '{{IF_RELOCATION}}', '')
            replace_in_runs(paragraph, '{{END_IF_RELOCATION}}', '')
        else:
            start = combined.find('{{IF_RELOCATION}}')
            end = combined.find('{{END_IF_RELOCATION}}')
            if start != -1 and end != -1 and end >= start:
                end += len('{{END_IF_RELOCATION}}')
                replace_range_in_runs(paragraph, start, end, '')
                removed_conditional = True
    # replace placeholders
    for key, value in replacements.items():
        token = '{{' + key + '}}'
        replace_in_runs(paragraph, token, value)

    if removed_conditional:
        if paragraph.text.strip() == '':
            p = paragraph._element
            p.getparent().remove(p)


def iter_paragraphs(container):
    # paragraphs directly in container
    for p in container.paragraphs:
        yield p
    # tables in container
    for table in container.tables:
        for row in table.rows:
            for cell in row.cells:
                for p in iter_paragraphs(cell):
                    yield p


doc = Document(TEMPLATE_PATH)

# main document
for p in iter_paragraphs(doc):
    process_paragraph(p)

# headers/footers
for section in doc.sections:
    for p in iter_paragraphs(section.header):
        process_paragraph(p)
    for p in iter_paragraphs(section.footer):
        process_paragraph(p)

doc.save(OUTPUT_PATH)
print('Saved', OUTPUT_PATH)
